#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    vector<unsigned long> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    int mid = n / 2;
    vector<unsigned long> first_half, second_half;

    // Generate all subset sums for the left half
    function<void(int, unsigned long)> generate_sums_left = [&](int i, unsigned long total) {
        if (i == mid) {
            first_half.push_back(total);
        } else {
            generate_sums_left(i + 1, (total + a[i]) % m);
            generate_sums_left(i + 1, total);
        }
    };

    // Generate all subset sums for the right half
    function<void(int, unsigned long)> generate_sums_right = [&](int i, unsigned long total) {
        if (i == n) {
            second_half.push_back(total);
        } else {
            generate_sums_right(i + 1, (total + a[i]) % m);
            generate_sums_right(i + 1, total);
        }
    };

    generate_sums_left(0, 0);
    generate_sums_right(mid, 0);

    // Remove duplicates and sort
    set<unsigned long> unique_left_set(first_half.begin(), first_half.end());
    vector<unsigned long> unique_left(unique_left_set.begin(), unique_left_set.end());

    unsigned long max_sum_found = 0;
    for (auto val : second_half) {
        auto it = std::lower_bound(unique_left.begin(), unique_left.end(), m - val);
        if (it != unique_left.begin()) {
            --it;
            unsigned long candidate_sum = *it + val;
            if (candidate_sum > max_sum_found) {
                max_sum_found = candidate_sum;
            }
        }
    }

    cout << max_sum_found << "\n";

    return 0;
}
